	(12157, 125, 'मंत्रिमंडल नोटों में उन दिनांकों का उल्लेख करना,  जब परामर्श  किए गए मंत्रालयों/विभागों से टिप्पणियां प्राप्त हुईं।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3346.pdf', 'application/pdf', '445.7 KB', 1, 0, '2026-06-10 09:09:15', '2004-12-01 00:00:00'),
	(12158, 126, 'कार्योत्तर अनुमोदन प्राप्त करने या सूचना के लिए मंत्रिमंडल/मंत्रिमंडल समिति हेतु नोट समय पर प्रस्तुत करने के संबंध में निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3347.pdf', 'application/pdf', '66.4 KB', 1, 0, '2026-06-10 09:09:15', '2021-09-16 00:00:00'),
